// Small catalogue first; load only the paper the learner opens. Works offline too.
const paperLoadVersion='mobile-20261018-1',paperRequests=new Map();let paperNavigation=0;
function loadPaperScript(file,ready){return new Promise((resolve,reject)=>{const tag=document.createElement('script');let timer=setTimeout(()=>finish(new Error('timeout')),15000);function finish(error){clearTimeout(timer);tag.onload=tag.onerror=null;tag.remove();error?reject(error):resolve()}tag.onload=()=>finish(ready()?null:new Error('incomplete'));tag.onerror=()=>finish(new Error('network'));tag.src=file+(file.includes('?')?'&':'?')+'v='+paperLoadVersion;document.head.append(tag)})}
function ensurePaper(id){let existing=allTests().find(t=>t.id===id);if(!existing||!existing.lazy)return Promise.resolve(existing);if(paperRequests.has(id))return paperRequests.get(id);let job=(async()=>{let cached=window.IELTS_PAPER_CACHE?.[id];for(let attempt=0;!cached&&attempt<3;attempt++){try{await loadPaperScript('papers/'+encodeURIComponent(id)+'.js',()=>!!window.IELTS_PAPER_CACHE?.[id]);cached=window.IELTS_PAPER_CACHE[id]}catch(error){if(attempt===2)throw error}}if(!cached?.parts?.every(p=>p.questions?.length))throw new Error('incomplete');library=library.map(t=>t.id===id?cached:t);return cached})();paperRequests.set(id,job);job.then(()=>paperRequests.delete(id),()=>paperRequests.delete(id));return job}
function paperLoading(){document.querySelector('.paper-loading')?.remove();let panel=document.createElement('section');panel.className='paper-loading';panel.setAttribute('role','status');panel.innerHTML='<div class="paper-loading-card"><h2>正在加载题目</h2><p>请稍候，首次打开这套题需要下载题目内容。</p><button class="secondary" data-load-cancel>取消</button></div>';document.body.append(panel);panel.querySelector('[data-load-cancel]').onclick=()=>{paperNavigation++;panel.remove()};return panel}
function paperLoadError(panel,retry){panel.setAttribute('role','alert');panel.querySelector('h2').textContent='题目暂时没有加载成功';panel.querySelector('p').textContent='请检查网络后重试。你的作答和已选音频会保留；也可以换用手机自带浏览器打开。';let button=document.createElement('button');button.className='primary';button.textContent='重新加载题目';button.onclick=()=>{panel.remove();retry()};panel.querySelector('.paper-loading-card').append(button)}
const startWithPaper=start,resultWithPaper=showResult;
start=function(t,options={}){if(!t?.lazy)return startWithPaper(t,options);const ticket=++paperNavigation,panel=paperLoading();return ensurePaper(t.id).then(loaded=>{if(ticket!==paperNavigation)return;panel.remove();startWithPaper(loaded,options)},()=>{if(ticket===paperNavigation)paperLoadError(panel,()=>start(t,options))})};
showResult=function(h){let t=allTests().find(t=>t.id===h.testId);if(!t?.lazy)return resultWithPaper(h);const ticket=++paperNavigation,panel=paperLoading();return ensurePaper(t.id).then(()=>{if(ticket!==paperNavigation)return;panel.remove();resultWithPaper(h)},()=>{if(ticket===paperNavigation)paperLoadError(panel,()=>showResult(h))})};
function recoverCatalogue(){const ticket=++paperNavigation,panel=paperLoading();panel.querySelector('h2').textContent='正在加载题库目录';return loadPaperScript('catalog.js',()=>Array.isArray(window.IELTS_LIBRARY)&&window.IELTS_LIBRARY.length>0).then(()=>{if(ticket!==paperNavigation)return;library=window.IELTS_LIBRARY;panel.remove();home()},()=>{if(ticket===paperNavigation)paperLoadError(panel,recoverCatalogue)})}
if(!library.length)recoverCatalogue();
